<?php require_once 'config.php';require_role('admin');$pageTitle='Admin console';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='announcement'){$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');if($title&&$body){$s=db()->prepare('INSERT INTO announcements(title,body,created_by) VALUES(?,?,?)');$s->execute([$title,$body,current_user()['id']]);flash('Announcement published.');redirect('admin.php');}else $message='Enter an announcement title and message.';}elseif($action==='user_status'){$id=(int)($_POST['user_id']??0);$status=($_POST['status']??'active')==='inactive'?'inactive':'active';if($id!==current_user()['id']){$s=db()->prepare('UPDATE users SET status=? WHERE id=?');$s->execute([$status,$id]);flash('User status updated.');redirect('admin.php');}}}
$users=db()->query('SELECT id,name,email,role,status,created_at FROM users ORDER BY created_at DESC')->fetchAll();$courseCount=(int)db()->query('SELECT COUNT(*) FROM courses')->fetchColumn();$enrollCount=(int)db()->query('SELECT COUNT(*) FROM enrollments')->fetchColumn();$assessmentCount=(int)db()->query('SELECT COUNT(*) FROM assessments')->fetchColumn();require 'includes/header.php'; ?>
<section class="dashboard-welcome"><div><span class="eyebrow">ADMINISTRATION</span><h1>Platform <em>overview.</em></h1><p>Monitor users, learning activity and platform communications.</p></div><a class="btn btn-primary" href="trainer.php">Manage courses →</a></section><section class="stats-grid"><div class="stat-card"><span class="stat-icon blue">♙</span><span>Registered users</span><strong><?= count($users) ?></strong><small>Trainees, trainers and admins</small></div><div class="stat-card"><span class="stat-icon green">▤</span><span>Courses</span><strong><?= $courseCount ?></strong><small>Across the platform</small></div><div class="stat-card"><span class="stat-icon orange">↗</span><span>Enrollments</span><strong><?= $enrollCount ?></strong><small><?= $assessmentCount ?> assessments created</small></div></section><?php if($message): ?><div class="alert error"><?= e($message) ?></div><?php endif; ?><section class="section dashboard-section"><div class="section-heading"><div><span class="eyebrow">PEOPLE & ACCESS</span><h2>User management</h2></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Joined</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($users as $usr): ?><tr><td><b><?= e($usr['name']) ?></b><small><?= e($usr['email']) ?></small></td><td><?= e(ucfirst($usr['role'])) ?></td><td><?= e(date('d M Y',strtotime($usr['created_at']))) ?></td><td><span class="status-pill <?= e($usr['status']) ?>"><?= e(ucfirst($usr['status'])) ?></span></td><td><?php if($usr['id']!==current_user()['id']): ?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="user_status"><input type="hidden" name="user_id" value="<?= (int)$usr['id'] ?>"><input type="hidden" name="status" value="<?= $usr['status']==='active'?'inactive':'active' ?>"><button class="btn btn-small <?= $usr['status']==='active'?'btn-outline':'btn-primary' ?>"><?= $usr['status']==='active'?'Deactivate':'Activate' ?></button></form><?php else: ?><span class="muted">You</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="section dashboard-section"><div class="section-heading"><div><span class="eyebrow">PLATFORM COMMUNICATION</span><h2>Publish an announcement</h2></div></div><div class="panel"><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="announcement"><label>Announcement title<input name="title" required placeholder="e.g. New learning resources available"></label><label>Message<textarea name="body" rows="4" required placeholder="Write an update for platform users..."></textarea></label><button class="btn btn-primary">Publish announcement →</button></form></div></section><?php require 'includes/footer.php'; ?>
